# interleave into NAMES order: chongle/dongle pairs per form, then the settings strings
T = {lang: [x for pair in zip(ch, dg) for x in pair] + list(st) + list(LANG[lang]) + list(CHARGED[lang]) + list(SOUNDS[lang]) + list(VIA[lang]) + list(DETAILS[lang]) + list(TRAY[lang]) for lang, (ch, dg, st) in L.items()}
